"use client"

import React, { createContext, useContext, useState, useEffect } from 'react'

interface ApiCall {
  timestamp: number
  tokens: number
}

interface ApiContextType {
  apiKey: string
  model: string
  isValid: boolean
  isLoading: boolean
  dailyUsage: number
  maxDailyUsage: number
  dailyTokens: number
  currentRPM: number
  currentTPM: number
  setApiKey: (key: string) => Promise<boolean>
  setModel: (model: string) => void
  validateKey: () => Promise<boolean>
  incrementUsage: (metadata?: any) => void
}

const ApiContext = createContext<ApiContextType | undefined>(undefined)

export function ApiProvider({ children }: { children: React.ReactNode }) {
  const [apiKey, setApiKeyState] = useState('')
  const [model, setModelState] = useState('gemini-1.5-flash-001')
  const [isValid, setIsValid] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  
  // Usage tracking
  const [dailyUsage, setDailyUsage] = useState(0)
  const [dailyTokens, setDailyTokens] = useState(0)
  const [recentCalls, setRecentCalls] = useState<ApiCall[]>([])
  const [currentRPM, setCurrentRPM] = useState(0)
  const [currentTPM, setCurrentTPM] = useState(0)
  
  const maxDailyUsage = 1500
  const maxRPM = 15
  const maxTPM = 1000000

  // Refresh real-time stats (RPM/TPM)
  useEffect(() => {
    const timer = setInterval(() => {
      const now = Date.now()
      const oneMinuteAgo = now - 60000
      
      setRecentCalls(prev => {
        const active = prev.filter(call => call.timestamp > oneMinuteAgo)
        setCurrentRPM(active.length)
        setCurrentTPM(active.reduce((sum, call) => sum + call.tokens, 0))
        return active
      })
    }, 5000)
    
    return () => clearInterval(timer)
  }, [])

  // Load initial state
  useEffect(() => {
    const storedKey = localStorage.getItem('user_gemini_key')
    const storedModel = localStorage.getItem('user_gemini_model')
    
    const today = new Date().toDateString()
    const lastUsageDate = localStorage.getItem('gemini_usage_date')
    const storedUsage = parseInt(localStorage.getItem('gemini_daily_usage') || '0', 10)
    const storedTokens = parseInt(localStorage.getItem('gemini_daily_tokens') || '0', 10)

    if (lastUsageDate !== today) {
      setDailyUsage(0)
      setDailyTokens(0)
      localStorage.setItem('gemini_daily_usage', '0')
      localStorage.setItem('gemini_daily_tokens', '0')
      localStorage.setItem('gemini_usage_date', today)
    } else {
      setDailyUsage(storedUsage)
      setDailyTokens(storedTokens)
    }
    
    if (storedModel) setModelState(storedModel)
    
    if (storedKey) {
      setApiKeyState(storedKey)
      validateInternal(storedKey).then(valid => setIsValid(valid))
    }
  }, [])

  const incrementUsage = (metadata?: any) => {
    const tokens = metadata?.totalTokenCount || metadata?.total_tokens || 0
    const now = Date.now()

    setDailyUsage(prev => {
      const newVal = prev + 1
      localStorage.setItem('gemini_daily_usage', newVal.toString())
      return newVal
    })

    setDailyTokens(prev => {
      const newVal = prev + tokens
      localStorage.setItem('gemini_daily_tokens', newVal.toString())
      return newVal
    })

    setRecentCalls(prev => [...prev, { timestamp: now, tokens }])
    localStorage.setItem('gemini_usage_date', new Date().toDateString())
  }

  const validateInternal = async (key: string): Promise<boolean> => {
    if (!key) return false
    setIsLoading(true)
    try {
      const response = await fetch('/api/validate-key', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ customApiKey: key })
      })
      
      if (response.ok) {
        setIsValid(true)
        return true
      } else {
        setIsValid(false)
        return false
      }
    } catch (e) {
      setIsValid(false)
      return false
    } finally {
      setIsLoading(false)
    }
  }

  const setApiKey = async (key: string): Promise<boolean> => {
    setApiKeyState(key)
    localStorage.setItem('user_gemini_key', key)
    const valid = await validateInternal(key)
    return valid
  }

  const setModel = (newModel: string) => {
    setModelState(newModel)
    localStorage.setItem('user_gemini_model', newModel)
  }

  const validateKey = async () => {
    return validateInternal(apiKey)
  }

  return (
    <ApiContext.Provider value={{ 
      apiKey, model, isValid, isLoading, 
      dailyUsage, maxDailyUsage, dailyTokens,
      currentRPM, currentTPM,
      setApiKey, setModel, validateKey, incrementUsage 
    }}>
      {children}
    </ApiContext.Provider>
  )
}

export function useApi() {
  const context = useContext(ApiContext)
  if (context === undefined) {
    throw new Error('useApi must be used within an ApiProvider')
  }
  return context
}
