"use client"

import { useLanguage } from "./LanguageContext"
import { motion } from "framer-motion"

export function LanguageToggle() {
  const { language, setLanguage } = useLanguage()

  return (
    <button
      onClick={() => setLanguage(language === 'en' ? 'mm' : 'en')}
      className="text-[10px] font-bold tracking-[0.2em] uppercase hover:opacity-50 transition-opacity flex items-center gap-1"
      aria-label="Toggle language"
    >
      <span className={language === 'en' ? 'text-foreground' : 'text-foreground/30'}>EN</span>
      <span className="text-foreground/20">/</span>
      <span className={language === 'mm' ? 'text-foreground' : 'text-foreground/30'}>MM</span>
    </button>
  )
}
